1	import { all, get, run } from '../db/index.js';
2	
3	export interface Book {
4	  id: number;
5	  title: string;
6	  author: string;
7	  isbn: string | null;
8	  cover_url: string | null;
9	  description: string | null;
10	  published_year: number | null;
11	  created_at: string;
12	}
13	
14	export function getAllBooks(): Book[] {
15	  return all('SELECT * FROM books ORDER BY title') as unknown as Book[];
16	}
17	
18	export function getBookById(id: number): Book | undefined {
19	  return get('SELECT * FROM books WHERE id = ?', [id]) as unknown as Book | undefined;
20	}
21	
22	export function searchBooks(query: string): Book[] {
23	  const pattern = `%${query}%`;
24	  return all(
25	    'SELECT * FROM books WHERE title LIKE ? OR author LIKE ? ORDER BY title',
26	    [pattern, pattern]
27	  ) as unknown as Book[];
28	}
29	
30	export function createBook(data: Omit<Book, 'id' | 'created_at'>): Book {
31	  const result = run(
32	    'INSERT INTO books (title, author, isbn, cover_url, description, published_year) VALUES (?, ?, ?, ?, ?, ?)',
33	    [data.title, data.author, data.isbn, data.cover_url, data.description, data.published_year]
34	  );
35	  return getBookById(result.lastInsertRowid)!;
36	}
37	
38	export function updateBook(id: number, data: Partial<Omit<Book, 'id' | 'created_at'>>): Book | undefined {
39	  const existing = getBookById(id);
40	  if (!existing) return undefined;
41	
42	  const updates: string[] = [];
43	  const values: unknown[] = [];
44	
45	  if (data.title !== undefined) {
46	    updates.push('title = ?');
47	    values.push(data.title);
48	  }
49	  if (data.author !== undefined) {
50	    updates.push('author = ?');
51	    values.push(data.author);
52	  }
53	  if (data.isbn !== undefined) {
54	    updates.push('isbn = ?');
55	    values.push(data.isbn);
56	  }
57	  if (data.cover_url !== undefined) {
58	    updates.push('cover_url = ?');
59	    values.push(data.cover_url);
60	  }
61	  if (data.description !== undefined) {
62	    updates.push('description = ?');
63	    values.push(data.description);
64	  }
65	  if (data.published_year !== undefined) {
66	    updates.push('published_year = ?');
67	    values.push(data.published_year);
68	  }
69	
70	  if (updates.length === 0) return existing;
71	
72	  values.push(id);
73	  run(`UPDATE books SET ${updates.join(', ')} WHERE id = ?`, values);
74	  return getBookById(id);
75	}
76	
77	export function deleteBook(id: number): boolean {
78	  const result = run('DELETE FROM books WHERE id = ?', [id]);
79	  return result.changes > 0;
80	}
