1	import { all, get, run } from '../db/index.js';
2	
3	export interface Book {
4	  id: number;
5	  title: string;
6	  author: string;
7	  isbn: string | null;
8	  cover_url: string | null;
9	  description: string | null;
10	  published_year: number | null;
11	  created_at: string;
12	}
13	
14	export function getAllBooks(): Book[] {
15	  return all('SELECT * FROM books ORDER BY title') as unknown as Book[];
16	}
17	
18	export function getBookById(id: number): Book | undefined {
19	  return get('SELECT * FROM books WHERE id = ?', [id]) as unknown as Book | undefined;
20	}
21	
22	export function searchBooks(query: string): Book[] {
23	  const pattern = `%${query}%`;
24	  return all(
25	    'SELECT * FROM books WHERE title LIKE ? OR author LIKE ? ORDER BY title',
26	    [pattern, pattern]
27	  ) as unknown as Book[];
28	}
29	
30	export function createBook(data: Omit<Book, 'id' | 'created_at'>): Book {
31	  const result = run(
32	    'INSERT INTO books (title, author, isbn, cover_url, description, published_year) VALUES (?, ?, ?, ?, ?, ?)',
33	    [data.title, data.author, data.isbn, data.cover_url, data.description, data.published_year]
34	  );
35	  return getBookById(result.lastInsertRowid)!;
