1	import { all, get, run } from '../db/index.js';
2	
3	export interface Book {
4	  id: number;
5	  title: string;
6	  author: string;
7	  isbn: string | null;
8	  cover_url: string | null;
9	  description: string | null;
10	  published_year: number | null;
11	  created_at: string;
12	}
13	
14	export function getAllBooks(): Book[] {
15	  return all('SELECT * FROM books ORDER BY title') as unknown as Book[];
16	}
17	
18	export function getBookById(id: number): Book | undefined {
19	  return get('SELECT * FROM books WHERE id = ?', [id]) as unknown as Book | undefined;
20	}
21	
22	export class SearchValidationError extends Error {
23	  constructor(message: string) {
24	    super(message);
25	    this.name = 'SearchValidationError';
26	  }
27	}
28	
29	export function searchBooks(query: string): Book[] {
30	  const trimmed = query.trim();
31	
32	  if (trimmed.length > 100) {
33	    throw new SearchValidationError('Search query must be 100 characters or fewer');
34	  }
35	
36	  if (trimmed.length === 0) {
37	    return getAllBooks();
38	  }
39	
40	  const escaped = trimmed.replace(/\\/g, '\\\\').replace(/%/g, '\\%').replace(/_/g, '\\_');
41	  const pattern = `%${escaped}%`;
42	  return all(
43	    "SELECT * FROM books WHERE title LIKE ? ESCAPE '\\' OR author LIKE ? ESCAPE '\\' ORDER BY title",
44	    [pattern, pattern]
45	  ) as unknown as Book[];
46	}
47	
48	export function createBook(data: Omit<Book, 'id' | 'created_at'>): Book {
49	  const result = run(
50	    'INSERT INTO books (title, author, isbn, cover_url, description, published_year) VALUES (?, ?, ?, ?, ?, ?)',
51	    [data.title, data.author, data.isbn, data.cover_url, data.description, data.published_year]
52	  );
53	  return getBookById(result.lastInsertRowid)!;
54	}
55	
56	export function updateBook(id: number, data: Partial<Omit<Book, 'id' | 'created_at'>>): Book | undefined {
57	  const existing = getBookById(id);
58	  if (!existing) return undefined;
59	
60	  const updates: string[] = [];
61	  const values: unknown[] = [];
62	
63	  if (data.title !== undefined) {
64	    updates.push('title = ?');
65	    values.push(data.title);
66	  }
67	  if (data.author !== undefined) {
68	    updates.push('author = ?');
69	    values.push(data.author);
70	  }
71	  if (data.isbn !== undefined) {
72	    updates.push('isbn = ?');
73	    values.push(data.isbn);
74	  }
75	  if (data.cover_url !== undefined) {
76	    updates.push('cover_url = ?');
77	    values.push(data.cover_url);
78	  }
79	  if (data.description !== undefined) {
80	    updates.push('description = ?');
81	    values.push(data.description);
82	  }
83	  if (data.published_year !== undefined) {
84	    updates.push('published_year = ?');
85	    values.push(data.published_year);
86	  }
87	
88	  if (updates.length === 0) return existing;
89	
90	  values.push(id);
91	  run(`UPDATE books SET ${updates.join(', ')} WHERE id = ?`, values);
92	  return getBookById(id);
93	}
94	
95	export function deleteBook(id: number): boolean {
96	  const result = run('DELETE FROM books WHERE id = ?', [id]);
97	  return result.changes > 0;
98	}
